import{_ as t,o,c as s,a2 as a}from"./chunks/framework.C1aUlgNS.js";const u=JSON.parse('{"title":"The web workspace","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workspace.md","filePath":"guide/workspace.md"}'),r={name:"guide/workspace.md"};function n(i,e,d,l,h,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-web-workspace" tabindex="-1">The web workspace <a class="header-anchor" href="#the-web-workspace" aria-label="Permalink to &quot;The web workspace&quot;">​</a></h1><p>The workspace is where you keep, edit and run your test files. It looks like a code editor: the sidebar on the left, the editor in the middle, and two consoles on the right.</p><h2 id="projects-folders-and-test-files" tabindex="-1">Projects, folders and test files <a class="header-anchor" href="#projects-folders-and-test-files" aria-label="Permalink to &quot;Projects, folders and test files&quot;">​</a></h2><p>The sidebar lists your <strong>Projects</strong>. A Project is a top-level folder, usually one per app you test, and holds your test files directly or in <strong>folders</strong>. Folders can hold folders, up to 4 levels counting the Project.</p><table tabindex="0"><thead><tr><th>In the sidebar</th><th>What it does</th></tr></thead><tbody><tr><td><strong>+</strong> next to &quot;Projects&quot;</td><td>Adds a Project; type its name in place and press Enter</td></tr><tr><td><strong>+</strong> on a Project or folder</td><td><strong>New folder</strong>, <strong>New test file</strong>, or <strong>Upload files…</strong></td></tr><tr><td><strong>Variables</strong> under a Project</td><td>Opens the Project&#39;s Variables</td></tr><tr><td>Drag and drop</td><td>Moves a folder or test file to another Project or folder. Dropping <code>.yaml</code> files or folders from your computer imports them</td></tr><tr><td><strong>Rename</strong>, <strong>Delete</strong>, <strong>Move to…</strong></td><td>On every row; F2 renames the focused row</td></tr><tr><td>The icon in front of a file</td><td>The latest Run: passed, failed, running, or never run</td></tr></tbody></table><p>Names of Projects and folders can be up to 100 characters. Test file names use only letters, digits, <code>-</code>, <code>_</code> and <code>.</code>, and end in <code>.yaml</code>. Uploading never overwrites a file: one whose name is taken is skipped with the reason.</p><p>A file&#39;s Runs stay with it when you rename or move it. Deleting a file deletes its history; a new file with the same name starts fresh.</p><p>The workspace&#39;s home page lists every test file with the status of its latest Run.</p><h2 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h2><p>A test file opens in the editor, with YAML highlighting and line numbers. The badge next to the file name says whether it is <strong>Saved</strong> or <strong>Unsaved</strong>, and how its latest Run ended.</p><table tabindex="0"><thead><tr><th>Do</th><th>How</th></tr></thead><tbody><tr><td>Save</td><td><strong>Save</strong> or <code>Ctrl+S</code> (<code>Cmd+S</code> on a Mac)</td></tr><tr><td>Run</td><td><strong>Run</strong> or <code>Ctrl+Enter</code>; unsaved changes are saved first</td></tr><tr><td>Jump to a problem</td><td>Click it in the Debug console</td></tr></tbody></table><p>The file is checked as you type and when you save. Each problem is underlined on its line, with the message on hover.</p><h2 id="the-debug-console" tabindex="-1">The Debug console <a class="header-anchor" href="#the-debug-console" aria-label="Permalink to &quot;The Debug console&quot;">​</a></h2><p>The <strong>Debug console</strong>, at the top right, lists the file&#39;s problems, one line each: <code>Line &lt;line&gt;: &lt;message&gt;</code> and the problem&#39;s code, such as <code>E005</code>. &quot;No problems&quot; means the file is valid. A file with problems cannot run: <strong>Run</strong> answers with the problems instead. The <a href="./../reference/diagnostics.html">Diagnostics</a> page explains every code and how to fix it.</p><p>When an agent wrote the file, copy the Debug console&#39;s lines and paste them back to the agent to fix.</p><h2 id="the-output-console-and-runs" tabindex="-1">The Output console and Runs <a class="header-anchor" href="#the-output-console-and-runs" aria-label="Permalink to &quot;The Output console and Runs&quot;">​</a></h2><p>The <strong>Output console</strong>, below the Debug console, follows the current Run live: its status, how many steps passed, and one line per step with its status and, for a failed step, the reason. Below it, <strong>Runs</strong> lists the file&#39;s earlier Runs, newest first.</p><p>Each console opens and collapses on its own from its header, and the toggle in the header or the status bar hides the whole column, so the editor takes the full width.</p><h2 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h2><p><strong>Open run details</strong>, or a Run in the list, opens the report beside the editor; <strong>Open full page</strong> opens it on its own page. A report shows:</p><ul><li>the Run&#39;s status, when it started, its duration, and how many steps passed;</li><li>every step, with its action, its line in the file, its status and duration, how its element was found (<code>selector</code>, <code>visual</code> or <code>dom</code>), and the reason when it failed;</li><li>a screenshot of the page after each step; click it to see it full size;</li><li><strong>Source when it ran</strong>: the file as it was when the Run started, since you may have edited it since;</li><li><strong>Download report</strong>, the report as JSON, and <strong>Download trace</strong>, a Playwright trace. Open the trace at <a href="https://trace.playwright.dev" target="_blank" rel="noreferrer">trace.playwright.dev</a> to step through the Run with the page, its network requests and its console.</li></ul><p>A Run stops at its first failed step; the steps after it stay <strong>Pending</strong>.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to &quot;Variables&quot;">​</a></h2><p>A Variable is a named value that test files use as <code>{{NAME}}</code>, such as <code>baseUrl: &quot;{{BASE}}&quot;</code> or <code>value: &quot;{{APP_PASSWORD}}&quot;</code>. Variables belong to a Project; every test file in the Project, in any folder, uses them.</p><p>Open <strong>Variables</strong> under a Project to add, change or delete them. Names use capital letters, digits and <code>_</code>, and do not start with a digit. Values are hidden as <code>****</code> until you click the eye button.</p><p>When a Run starts, every <code>{{NAME}}</code> in the file is replaced with the Variable&#39;s value. A Variable the Project does not have fails the step that uses it with <code>Variable {{NAME}} is not set</code>. Values are hidden in reports and failure reasons, which show <code>{{NAME}}</code> instead.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>The workspace follows your system&#39;s light or dark setting. The theme switch next to your account, at the bottom of the sidebar, picks <strong>Light</strong>, <strong>Dark</strong> or <strong>System</strong>.</p>',28)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
